WITH UserDaily AS (SELECT spend_date, user_id, CASE WHEN COUNT(DISTINCT platform) = 2 THEN 'both' ELSE MAX(platform) END AS platform, SUM(amount) AS total_amount FROM Spending GROUP BY spend_date, user_id), Dates AS (SELECT DISTINCT spend_date FROM Spending), Platforms AS (SELECT 'desktop' AS platform UNION ALL SELECT 'mobile' UNION ALL SELECT 'both'), Grid AS (SELECT d.spend_date, p.platform FROM Dates d CROSS JOIN Platforms p) SELECT g.spend_date, g.platform, IFNULL(SUM(u.total_amount), 0) AS total_amount, COUNT(u.user_id) AS total_users FROM Grid g LEFT JOIN UserDaily u ON g.spend_date = u.spend_date AND g.platform = u.platform GROUP BY g.spend_date, g.platform;
